from collections import deque

def window_max(a, k):
    dq = deque()                     # 放 index，對應的值由前到後遞減
    res = []
    for i, x in enumerate(a):
        while dq and a[dq[-1]] <= x:
            dq.pop()                 # 比 x 小的以後都不可能是最大
        dq.append(i)
        if dq[0] <= i - k:
            dq.popleft()             # 滑出視窗了
        if i >= k - 1:
            res.append(a[dq[0]])
    return res

print(window_max([1, 3, -1, -3, 5, 3, 6, 7], 3))   # [3, 3, 5, 5, 6, 7]

