# 從左上走到右下，只能往右或往下，有幾種走法？
def unique_paths(R, C):
    dp = [[0] * C for _ in range(R)]
    for r in range(R):
        for c in range(C):
            if r == 0 or c == 0:
                dp[r][c] = 1                       # 邊上只有一種走法
            else:
                dp[r][c] = dp[r - 1][c] + dp[r][c - 1]   # 兩個 child 都要算
    return dp[R - 1][C - 1]

