# 優先順序：數字越大越先算；"(" 不放進表裡，單獨處理
prec = {"+": 1, "-": 1, "*": 2, "/": 2}

tokens = input().split()
stack, out = [], []
for t in tokens:
    if t == "(":
        stack.append(t)
    elif t == ")":
        while stack[-1] != "(":          # 把括號裡的運算子全部輸出
            out.append(stack.pop())
        stack.pop()                       # 丟掉 "("
    elif t in prec:
        # 堆疊頂端的運算子「優先順序 >= 自己」就先輸出（同級要先輸出：左結合）
        while stack and stack[-1] != "(" and prec[stack[-1]] >= prec[t]:
            out.append(stack.pop())
        stack.append(t)
    else:                                  # 運算元：直接輸出
        out.append(t)
while stack:
    out.append(stack.pop())
print(" ".join(out))

