import sys

def main():
    data = sys.stdin.buffer.read().split()
    n, q = int(data[0]), int(data[1])
    a = [0] + [int(x) for x in data[2:2 + n]]
    by_r = [[] for _ in range(n + 1)]                 # 依右端點把查詢分組
    for i in range(q):
        l, r = int(data[2 + n + 2 * i]), int(data[3 + n + 2 * i])
        by_r[r].append((l, i))

    tree = [0] * (n + 1)                              # Fenwick tree
    def add(i, v):
        while i <= n:
            tree[i] += v; i += i & -i
    def prefix(i):
        s = 0
        while i > 0:
            s += tree[i]; i -= i & -i
        return s

    last = {}                                         # 每個值「最後一次」出現的位置
    ans = [0] * q
    for r in range(1, n + 1):
        x = a[r]
        if x in last:
            add(last[x], -1)                          # 舊的位置不算了
        add(r, 1)                                     # 只在最右邊的位置記 1
        last[x] = r
        for l, i in by_r[r]:
            ans[i] = prefix(r) - prefix(l - 1)        # [l, r] 裡標 1 的數量 = 不同值的個數
    print("\n".join(map(str, ans)))

main()
